const invoices = $('Get Not Paid Invoices').first().json.result;
const payments = $('Parse Data').all().map(i => i.json);

const normalizeVendor = v =>
  (v || '')
    .toString()
    .toUpperCase()
    .replace(/\bPE\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeInvoiceName = v =>
  (v || '')
    .toString()
    .toUpperCase()
    .replace(/\s+/g, '');

const isSameAmount = (a, b) =>
  Math.abs(Number(a) - Number(b)) <= 0.05;

const matched = [];
const unMatched = [];
const usedInvoiceIds = new Set();

payments.forEach(payment => {
  const paymentAmount = Math.abs(Number(payment.amount));
  const reasons = [];

  // 1️⃣ Пошук по номеру інвойсу
  let invoice = invoices.find(inv =>
    !usedInvoiceIds.has(inv.id) &&
    normalizeInvoiceName(inv.name) === normalizeInvoiceName(payment.odoo_name)
  );

  // 2️⃣ Fallback: вендор + сума
  if (!invoice) {
    const paymentVendorNorm = normalizeVendor(payment.partner_name);

    const candidates = invoices.filter(inv =>
      !usedInvoiceIds.has(inv.id) &&
      normalizeVendor(inv.partner_id?.[1]) === paymentVendorNorm &&
      isSameAmount(inv.amount_residual, paymentAmount)
    );

    if (candidates.length === 1) {
      invoice = candidates[0];
    } else if (candidates.length > 1) {
      reasons.push({
        reason: 'MULTIPLE_INVOICES_FOUND_BY_VENDOR_AND_AMOUNT',
        vendor: payment.partner_name,
        paymentAmount,
        invoiceIds: candidates.map(i => i.id)
      });
    } else {
      reasons.push('INVOICE_NOT_FOUND_BY_NAME');
    }
  }

  // 3️⃣ Перевірка суми (ОБОВʼЯЗКОВА)
  if (invoice) {
    if (!isSameAmount(invoice.amount_residual, paymentAmount)) {
      reasons.push({
        reason: 'AMOUNT_MISMATCH',
        invoiceAmount: invoice.amount_residual,
        paymentAmount
      });
    }
  }

  // 4️⃣ Результат
  if (invoice && reasons.length === 0) {
    usedInvoiceIds.add(invoice.id);
    matched.push({ payment, invoice });
  } else {
    unMatched.push({ payment, reasons });
  }
});

return [
  {
    json: {
      matched,
      unMatched
    }
  }
];

const payments = $('non-attached transaction journal data').first().json.result;

const parsedPayments = payments.map(p => {
  let transactionDetails = null;
  let odoo_name = null;

  if (p.transaction_details) {
    transactionDetails = JSON.parse(p.transaction_details);

    // Беремо description та інформацію з extra
    const description = transactionDetails.description || '';
    const extraInfo = transactionDetails.extra?.information || '';

    // З’єднуємо обидва тексти та прибираємо всі пробіли і перенос рядка
    const cleanText = (description + ' ' + extraInfo).replace(/\s+/g, '');

    // Шукаємо BILLH з форматом BILLH/РРРР/ММ/номер (номер може бути відсутнім або частковим)
    const match = cleanText.match(/BILLH\/\d{4}\/\d{2}\/?\d*/i);

    if (match) {
      odoo_name = match[0].toUpperCase(); // Нормалізуємо великими літерами
    }
  }

  return {
    ...p,
    transaction_details: transactionDetails,
    odoo_name,
  };
});

return parsedPayments;

