let  date = $now.plus({ hours: 24 })

// Проверка дня недели (1 = понедельник, 7 = воскресенье)
let day = date.weekday;
let hour = date.hour;

// Если выходные → переносим на понедельник 12:00
if (day === 6) { // суббота
  date = date.plus({ days: 2 }).set({ hour: 12, minute: 0, second: 0 });
} else if (day === 7) { // воскресенье
  date = date.plus({ days: 1 }).set({ hour: 12, minute: 0, second: 0 });
} else {
  // Если нерабочее время (до 9 или после 19) → следующий рабочий день в 12:00
  if (hour < 9 || hour >= 19) {
    date = date.plus({ days: 1 }).set({ hour: 12, minute: 0, second: 0 });

    // Если следующий день оказался выходным — переносим на понедельник
    let nextDay = date.weekday;
    if (nextDay === 6) { // суббота
      date = date.plus({ days: 2 });
    } else if (nextDay === 7) { // воскресенье
      date = date.plus({ days: 1 });
    }
  }
}

return  { deadline: date.toFormat('yyyy-MM-dd HH:mm:ss') }

