const taskId = $input.first().json.result.task.id; // ID створеної задачі
const items = $('Matching Items').first().json.unMatched;

return items.map((i) => {
    const paymentName = i.payment?.name || 'Не знайдено';
    const odooName = i.payment?.odoo_name || 'Не знайдено';
    const amount = Math.abs(Number(i.payment?.amount || 0)).toFixed(2);

    let reason = 'Невідома причина';
    const r = i.reasons?.[0];

    if (r === 'INVOICE_NOT_FOUND_BY_NAME' || r?.reason === 'INVOICE_NOT_FOUND_BY_NAME') {
        reason = 'Інвойс з таким номером не знайдено';
    }

    if (r?.reason === 'AMOUNT_MISMATCH') {
        reason = `Сума не відповідає інвойсу (invoice: ${r.invoiceAmount} EUR, payment: ${r.paymentAmount} EUR)`;
    }

    return {
        json: {
            TASKID: taskId,
            FIELDS: {
                TITLE: `Odoo name: ${odooName}, Payment name: ${paymentName}, Amount: ${amount} EUR, Reason: ${reason}`
            }
        }
    };
});

const taskId = $('Task id').first().json.task_id;  
const items = $('Matching Items').first().json.unMatched;
const checkList = $('Get Checklist').first().json.result || []; // існуючий чеклист

// функція для спрощеного порівняння TITLE
function normalizeTitle(title) {
    return title.replace(/\s+/g, ' ').trim().toLowerCase();
}

// створюємо Set існуючих назв чеклістів
const existingTitles = new Set(checkList.map(c => normalizeTitle(c.TITLE)));

const newItems = items
    .map((i) => {
        const paymentName = i.payment?.name || 'Не знайдено';
        const odooName = i.payment?.odoo_name || 'Не знайдено';
        const amount = Math.abs(Number(i.payment?.amount || 0)).toFixed(2);

        let reason = 'Невідома причина';
        const r = i.reasons?.[0];

        if (r === 'INVOICE_NOT_FOUND_BY_NAME' || r?.reason === 'INVOICE_NOT_FOUND_BY_NAME') {
            reason = 'Інвойс з таким номером не знайдено';
        } else if (r?.reason === 'AMOUNT_MISMATCH') {
            reason = `Сума не відповідає інвойсу (invoice: ${r.invoiceAmount} EUR, payment: ${r.paymentAmount} EUR)`;
        }

        const title = `Odoo name: ${odooName}, Payment name: ${paymentName}, Amount: ${amount} EUR, Reason: ${reason}`;

        // повертаємо null, якщо такий title вже існує
        return existingTitles.has(normalizeTitle(title)) ? null : {
            json: {
                TASKID: taskId,
                FIELDS: { TITLE: title }
            }
        };
    })
    .filter(Boolean); // видаляємо null

// якщо нових айтемів немає
if (newItems.length === 0) {
    return [{ json: { allAlreadyInChecklist: true } }];
}

return newItems;

